using GraphApi.Models.TKT.DocumentosTicket;namespace GraphApi.Services.TKT.DocumentosTicket{    /// <summary>    /// Define las operaciones de negocio y persistencia para DocumentosTickets.    /// </summary>    public interface IDocumentosTicketService    {        /// <summary>        /// Obtiene la lista de DocumentosTickets con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadDocumentosTicket>> GetDocumentosTickets(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de DocumentosTickets con filtros opcionales.        /// </summary>        /// <param name="documentoTicketID">Filtro opcional para DocumentoTicketID.</param>        /// <param name="ticketID">Filtro opcional para TicketID.</param>        /// <param name="documentoID">Filtro opcional para DocumentoID.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetDocumentosTicketsDynamic(            int? documentoTicketID,            int? ticketID,            int? documentoID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo DocumentosTicket.        /// </summary>        /// <param name="objInput">Datos para crear el DocumentosTicket.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadDocumentosTicket> CreateDocumentosTicket(            clCreateDocumentosTicket objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un DocumentosTicket.        /// </summary>        /// <param name="objInput">Datos para actualizar el DocumentosTicket, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadDocumentosTicket?> UpdateDocumentosTicket(            clUpdateDocumentosTicket objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un DocumentosTicket por su ID.        /// </summary>        /// <param name="nDocumentosTicketID">ID del DocumentosTicket a eliminar.</param>        Task<bool> DeleteDocumentosTicket(int nDocumentosTicketID);    }}